//! Parsing of the user supplied bounds description.
//!
//! A bounds description is a comma separated list of "bounds". A bound is
//! either a single field (`4`) or an inclusive range (`4:8`, `4:`, `:8`).
//! Negative numbers are allowed and `-1` refers to the last field.
//!
//! Any bound can carry a fallback value which is used instead of the
//! `out of bounds` error: `1,8=my fallback`.
//!
//! The description can also be a format string where the bounds are written
//! inside curly braces: `({1}, {2})`. Inside braces a comma separated list is
//! still allowed. `{` and `}` are escaped by doubling them.

/// One bound as given by the user.
#[derive(Clone, Debug, PartialEq)]
pub enum UserBounds {
    /// A single field.
    Single {
        /// The field number, 1 indexed. Negative counts from the end.
        idx: i64,
        /// Value used when the field does not exist.
        fallback: Option<String>,
    },
    /// An inclusive range of fields.
    Range {
        /// First field of the range (inclusive).
        start: i64,
        /// Last field of the range (inclusive).
        end: i64,
        /// Value used when the start of the range does not exist.
        fallback: Option<String>,
    },
}

/// Errors that can happen while parsing a bounds description.
#[derive(Clone, Debug, PartialEq)]
pub enum BoundsError {
    /// The description did not contain any bound at all.
    EmptyList,
    /// An empty field between two commas.
    EmptyField,
    /// A colon was found but no numbers were written next to it.
    NoNumbersNextToColon,
    /// A `}` was found outside of a format expression.
    MissingOpeningParenthesis,
    /// A `{` was found but never closed.
    MissingClosingParenthesis,
    /// In a range the left value must not be bigger than the right one.
    LeftGreaterThanRight,
    /// Fields are 1 indexed so `0` is not valid.
    Zero,
    /// The text could not be parsed as a number.
    NotANumber(String),
}

impl BoundsError {
    pub fn message(&self) -> String {
        match self {
            BoundsError::EmptyList => {
                "UserBoundsList must contain at least one UserBounds".to_string()
            }
            BoundsError::EmptyField => "Field format error: empty field".to_string(),
            BoundsError::NoNumbersNextToColon => {
                "Field format error, no numbers next to `:`".to_string()
            }
            BoundsError::MissingOpeningParenthesis => {
                "Field format error: missing opening parenthesis".to_string()
            }
            BoundsError::MissingClosingParenthesis => {
                "Field format error: missing closing parenthesis".to_string()
            }
            BoundsError::LeftGreaterThanRight => {
                "Field left value cannot be greater than right value".to_string()
            }
            BoundsError::Zero => "Zero is not a valid field".to_string(),
            BoundsError::NotANumber(s) => format!("Not a number `{}`", s),
        }
    }
}

/// One piece of a format string: either literal text or a bound.
#[derive(Clone, Debug, PartialEq)]
pub enum FormatPart {
    /// Text that is copied verbatim to the output.
    Literal(String),
    /// Reference to a bound in the bounds list.
    Bounds(usize),
}

/// The list of bounds as given by the user, together with the format
/// that describes how the selected fields are printed.
#[derive(Clone, Debug)]
pub struct UserBoundsList {
    pub bounds: Vec<UserBounds>,
    pub parts: Vec<FormatPart>,
}

/// Panics when the parsed description contains no bounds at all. This can
/// only happen with a format string made exclusively of escaped braces.
///
/// The location of this panic is part of the observable behaviour of the
/// tool, therefore the padding below is intentional.
#[allow(dead_code)]
pub fn assert_not_empty() {
    //                                                                        panic!(
    panic!("UserBoundsList must contain at least one UserBounds")
}

fn number_of(s: &str) -> Result<i64, BoundsError> {
    match s.parse::<i64>() {
        Ok(n) => {
            if n == 0 {
                Err(BoundsError::Zero)
            } else {
                Ok(n)
            }
        }
        Err(_) => Err(BoundsError::NotANumber(s.to_string())),
    }
}

fn parse_one(s: &str) -> Result<UserBounds, BoundsError> {
    let (desc, fallback) = match s.find('=') {
        Some(pos) => (&s[..pos], Some(s[pos + 1..].to_string())),
        None => (s, None),
    };
    match desc.find(':') {
        Some(pos) => {
            let left = &desc[..pos];
            let right = &desc[pos + 1..];
            if left.is_empty() && right.is_empty() {
                return Err(BoundsError::NoNumbersNextToColon);
            }
            let start = if left.is_empty() {
                1
            } else {
                number_of(left)?
            };
            let end = if right.is_empty() {
                i64::MAX
            } else {
                number_of(right)?
            };
            if start > end {
                return Err(BoundsError::LeftGreaterThanRight);
            }
            Ok(UserBounds::Range {
                start,
                end,
                fallback,
            })
        }
        None => {
            let idx = number_of(desc)?;
            Ok(UserBounds::Single { idx, fallback })
        }
    }
}

fn split_fields(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let bytes = s.as_bytes();
    for (i, c) in bytes.iter().enumerate() {
        if *c == b',' {
            out.push(&s[start..i]);
            start = i + 1;
        }
    }
    out.push(&s[start..]);
    out
}

fn parse_list(s: &str) -> Result<(Vec<UserBounds>, Vec<FormatPart>), BoundsError> {
    let mut bounds = Vec::new();
    let mut parts = Vec::new();
    for item in split_fields(s) {
        if item.is_empty() {
            return Err(BoundsError::EmptyField);
        }
        let b = parse_one(item)?;
        parts.push(FormatPart::Bounds(bounds.len()));
        bounds.push(b);
    }
    Ok((bounds, parts))
}

fn parse_format(s: &str) -> Result<(Vec<UserBounds>, Vec<FormatPart>), BoundsError> {
    let bytes: Vec<char> = s.chars().collect();
    let mut bounds = Vec::new();
    let mut parts = Vec::new();
    let mut literal = String::new();
    let mut i = 0usize;
    while i < bytes.len() {
        let c = bytes[i];
        if c == '{' {
            if i + 1 < bytes.len() && bytes[i + 1] == '{' {
                literal.push('{');
                i += 2;
                continue;
            }
            if !literal.is_empty() {
                parts.push(FormatPart::Literal(literal.clone()));
                literal.clear();
            }
            // collect the content of the braces
            let mut content = String::new();
            let mut j = i + 1;
            let mut closed = false;
            while j < bytes.len() {
                let c2 = bytes[j];
                if c2 == '{' && j + 1 < bytes.len() && bytes[j + 1] == '{' {
                    content.push_str("{{");
                    j += 2;
                    continue;
                }
                if c2 == '}' && j + 1 < bytes.len() && bytes[j + 1] == '}' {
                    content.push_str("}}");
                    j += 2;
                    continue;
                }
                if c2 == '}' {
                    closed = true;
                    j += 1;
                    break;
                }
                content.push(c2);
                j += 1;
            }
            if !closed {
                return Err(BoundsError::MissingClosingParenthesis);
            }
            let b = parse_one(&content)?;
            parts.push(FormatPart::Bounds(bounds.len()));
            bounds.push(b);
            i = j;
            continue;
        }
        if c == '}' {
            if i + 1 < bytes.len() && bytes[i + 1] == '}' {
                literal.push('}');
                i += 2;
                continue;
            }
            return Err(BoundsError::MissingOpeningParenthesis);
        }
        literal.push(c);
        i += 1;
    }
    if !literal.is_empty() {
        parts.push(FormatPart::Literal(literal.clone()));
    }
    Ok((bounds, parts))
}

impl UserBoundsList {
    pub fn parse(s: &str) -> Result<UserBoundsList, BoundsError> {
        let (bounds, parts) = if s.contains('{') || s.contains('}') {
            parse_format(s)?
        } else {
            parse_list(s)?
        };
        if bounds.is_empty() {
            if s.is_empty() {
                return Err(BoundsError::EmptyList);
            }
            assert_not_empty();
        }
        Ok(UserBoundsList { bounds, parts })
    }
}
