//! Reading of the input, one line at a time.

/// Very small memory mapped input abstraction. The real tool maps the input
/// file into memory when possible. For our purposes reading everything into
/// a buffer is equivalent, `--no-mmap` only toggles this optimisation.
pub struct Input {
    data: Vec<u8>,
    mmap: bool,
}

impl Input {
    pub fn from_stdin(no_mmap: bool) -> Input {
        let mut data = Vec::new();
        use std::io::Read;
        let stdin = std::io::stdin();
        let mut lock = stdin.lock();
        let _ = lock.read_to_end(&mut data);
        Input { data, mmap: !no_mmap }
    }

    pub fn from_file(path: &str, no_mmap: bool) -> Result<Input, std::io::Error> {
        let data = std::fs::read(path)?;
        Ok(Input { data, mmap: !no_mmap })
    }

    pub fn len(&self) -> usize {
        self.data.len()
    }
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }
    pub fn bytes(&self) -> &[u8] {
        &self.data
    }
    pub fn use_mmap(&self) -> bool {
        self.mmap
    }
}

/// Iterator over the lines of the input. The line content is returned
/// *without* the line separator. The caller learns whether a separator was
/// present so that `--lines` can print it back.
pub struct LineReader {
    data: Vec<u8>,
    pos: usize,
    sep: u8,
}

impl LineReader {
    pub fn new(input: Input, sep: u8) -> LineReader {
        LineReader {
            data: input.bytes().to_vec(),
            pos: 0,
            sep,
        }
    }

    pub fn sep(&self) -> u8 {
        self.sep
    }

    /// Returns the next line (without the separator) and whether a
    /// separator terminated it.
    pub fn next_line(&mut self) -> Option<(Vec<u8>, bool)> {
        if self.pos >= self.data.len() {
            return None;
        }
        let rest = &self.data[self.pos..];
        match rest.iter().position(|c| *c == self.sep) {
            Some(i) => {
                let line = rest[..i].to_vec();
                self.pos += i + 1;
                Some((line, true))
            }
            None => {
                let line = rest.to_vec();
                self.pos = self.data.len();
                Some((line, false))
            }
        }
    }
}
