use crate::bounds::userboundslist::{FormatPart, UserBounds, UserBoundsList};
use crate::args::{Delim, Trim};
use crate::reader::{Input, LineReader};
use std::io::Write;

/// How the delimiter is described by the user.
/// `Trim` side for `--trim`.

/// Split `line` into the byte ranges of its fields. `matches` holds the
/// byte ranges of the delimiter occurrences.
pub fn field_ranges(line_len: usize, matches: &[(usize, usize)]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    if line_len == 0 {
        out.push((0, 0));
        return out;
    }
    let mut prev = 0usize;
    for (s, e) in matches {
        out.push((prev, *s));
        prev = *e;
    }
    out.push((prev, line_len));
    out
}

/// Find the delimiter occurrences in `line`.
pub fn find_matches(line: &[u8], delim: &Delim, greedy: bool) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    match delim {
        Delim::Str(d) => {
            if d.is_empty() {
                if line.is_empty() {
                    return out;
                }
                // an empty delimiter matches at every byte boundary
                let mut i = 0usize;
                while i <= line.len() {
                    out.push((i, i));
                    i += 1;
                }
                return out;
            }
            let mut i = 0usize;
            while i + d.len() <= line.len() {
