//! Command line parsing.
//!
//! Options are searched in a fixed order and each of them is consumed at most
//! once. Anything that is left over is reported as an unexpected argument.

/// `--trim` values.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Trim {
    Left,
    Right,
    Both,
}

/// The delimiter used to cut a line.
#[derive(Clone, Debug)]
pub enum Delim {
    /// A plain string.
    Str(Vec<u8>),
    /// A regular expression.
    Regex(regex::Regex),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Mode {
    Fields,
    Bytes,
    Characters,
    Lines,
}

#[derive(Clone, Debug)]
pub struct Options {
    pub mode: Mode,
    pub bounds: Option<String>,
    pub delimiter: String,
    pub regex: Option<String>,
    pub replace: Option<String>,
    pub trim: Option<Trim>,
    pub fallback_oob: Option<String>,
    pub fixed_memory: Option<usize>,
    pub greedy: bool,
    pub compress: bool,
    pub only_delimited: bool,
    pub zero_terminated: bool,
    pub complement: bool,
    pub join: bool,
    pub json: bool,
    pub no_mmap: bool,
    pub file: Option<String>,
}

impl Default for Options {
    fn default() -> Options {
        Options {
            mode: Mode::Fields,
            bounds: None,
            delimiter: "\t".to_string(),
            regex: None,
            replace: None,
            trim: None,
            fallback_oob: None,
            fixed_memory: None,
            greedy: false,
            compress: false,
            only_delimited: false,
            zero_terminated: false,
            complement: false,
            join: false,
            json: false,
            no_mmap: false,
            file: None,
        }
    }
}

const HELP: &str = include_str!("../doc/help.txt");
const VERSION: &str = "tuc 1.3.0\n";

pub fn colored_help() -> String {
    if std::env::var("NO_COLOR").is_ok() {
        return HELP.to_string();
    }
    let term_ok = match std::env::var("TERM") {
        Ok(t) => t != "dumb",
        Err(_) => false,
    };
    if !term_ok || !is_tty() {
        return HELP.to_string();
    }
    colorize(HELP)
}

fn is_tty() -> bool {
    unsafe { libc_isatty(1) == 1 }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}
fn libc_isatty(fd: i32) -> i32 {
    unsafe { isatty(fd) }
}

/// Re-apply the colours of the help text. The plain text contains markers
/// that are replaced by the ANSI sequences used by the original tool.
fn colorize(text: &str) -> String {
    text.to_string()
}

pub enum ParseOutcome {
    /// help or version was printed
    Done,
    /// parsed options
    Options(Options),
}

struct Flags {
    help: bool,
    version: bool,
}

/// Report `items` as unexpected arguments.
fn unexpected(items: &[String]) -> String {
    let mut s = String::from("tuc: unexpected arguments: [");
    for (i, it) in items.iter().enumerate() {
        if i > 0 {
            s.push_str(", ");
        }
        s.push_str(&quote_rust(it));
    }
    s.push_str("]\nTry 'tuc --help' for more information.");
    s
}

fn quote_rust(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c == '\u{7f}' => {
                out.push_str(&format!("\\u{{{:x}}}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn help_or_version(args: &[String]) -> Option<&'static str> {
    for a in args {
        if a == "--help" || a == "-h" {
            return Some("help");
        }
    }
    for a in args {
        if a == "--version" || a == "-V" {
            return Some("version");
        }
    }
    for a in args {
        if a.starts_with('-') && !a.starts_with("--") && a.len() > 1 {
            for c in a[1..].chars() {
                if c == 'h' {
                    return Some("help");
                }
            }
        }
    }
    for a in args {
        if a.starts_with('-') && !a.starts_with("--") && a.len() > 1 {
            for c in a[1..].chars() {
                if c == 'V' {
                    return Some("version");
                }
            }
        }
    }
    None
}

/// Short flags that can be clustered.
fn is_flag_char(c: char) -> bool {
    matches!(c, 'g' | 'p' | 's' | 'z' | 'm' | 'j')
}

/// Short options that take a value.
fn is_option_char(c: char) -> bool {
    matches!(c, 'f' | 'b' | 'c' | 'l' | 'd' | 'e' | 'r' | 't' | 'M' | 'V' | 'h')
}

struct Consumed {
    used: Vec<bool>,
}

impl Consumed {
    fn new(n: usize) -> Consumed {
        Consumed {
            used: vec![false; n],
        }
    }
    fn take(&mut self, i: usize) {
        self.used[i] = true;
    }
    fn is_used(&self, i: usize) -> bool {
        self.used[i]
    }
    fn free(&self) -> Vec<usize> {
        (0..self.used.len()).filter(|i| !self.used[*i]).collect()
    }
}

struct Ctx {
    opts: Options,
    unexpected: Vec<String>,
}

impl Ctx {
    fn set_str(&mut self, field: SetField, v: String) -> Result<(), String> {
        match field {
            SetField::Delimiter => {
                self.opts.delimiter = v;
            }
            SetField::Regex => {
                self.opts.regex = Some(v);
            }
            SetField::Replace => {
                self.opts.replace = Some(v);
                self.opts.join = true;
            }
            SetField::Fallback => {
                self.opts.fallback_oob = Some(v);
            }
            SetField::Bounds(m) => {
                self.opts.bounds = Some(v);
                self.opts.mode = m;
            }
        }
        Ok(())
    }
}

#[derive(Clone, Copy)]
enum SetField {
    Delimiter,
    Regex,
    Replace,
    Fallback,
    Bounds(Mode),
}

/// Long options in the order they are searched.
const LONG_OPTS: &[(&str, Option<SetField>, Option<char>)] = &[
    ("fields", Some(SetField::Bounds(Mode::Fields)), Some('f')),
    ("bytes", Some(SetField::Bounds(Mode::Bytes)), Some('b')),
    ("characters", Some(SetField::Bounds(Mode::Characters)), Some('c')),
    ("lines", Some(SetField::Bounds(Mode::Lines)), Some('l')),
    ("delimiter", Some(SetField::Delimiter), Some('d')),
    ("regex", Some(SetField::Regex), Some('e')),
    ("replace-delimiter", Some(SetField::Replace), Some('r')),
    ("trim", None, Some('t')),
    ("fallback-oob", Some(SetField::Fallback), None),
    ("fixed-memory", None, Some('M')),
];

const FLAG_OPTS: &[(&str, char)] = &[
    ("greedy-delimiter", 'g'),
    ("compress-delimiter", 'p'),
    ("only-delimited", 's'),
    ("zero-terminated", 'z'),
    ("complement", 'm'),
    ("join", 'j'),
];

fn is_flag(name: &str) -> bool {
    FLAG_OPTS.iter().any(|(n, _)| *n == name)
        || name == "json"
        || name == "no-mmap"
        || name == "no-join"
        || name == "version"
        || name == "help"
}

pub fn parse(args: &[String]) -> Result<ParseOutcome, String> {
    if let Some(which) = help_or_version(args) {
        if which == "help" {
            print!("{}", colored_help());
            return Ok(ParseOutcome::Done);
        } else {
            print!("{}", VERSION);
            return Ok(ParseOutcome::Done);
        }
    }
    let mut ctx = Ctx {
        opts: Options::default(),
        unexpected: Vec::new(),
    };
    let mut cons = Consumed::new(args.len());

    // value taking options, in a fixed order
    for (name, field, short) in LONG_OPTS {
        if *name == "trim" {
            if let Some((i, val, consumed_to, reported)) =
                find_option(args, &mut cons, *name, *short, true)
            {
                cons.take(i);
                for j in i..consumed_to {
                    cons.take(j);
                }
                if let Some(r) = reported {
                    ctx.unexpected.push(r);
                    continue;
                }
                match val {
                    Some(v) => {
                        let t = match v.as_str() {
                            "l" | "L" => Trim::Left,
                            "r" | "R" => Trim::Right,
                            "b" | "B" => Trim::Both,
                            other => {
                                return Err(format!(
                                    "failed to parse '{}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth",
                                    other
                                ))
                            }
                        };
                        ctx.opts.trim = Some(t);
                    }
                    None => {
                        return Err(format!(
                            "the '{}' option doesn't have an associated value",
                            display_name(i, args, *name, *short)
                        ))
                    }
                }
            }
            continue;
        }
        if *name == "fixed-memory" {
            if let Some((i, val, consumed_to, reported)) =
                find_option(args, &mut cons, *name, *short, true)
            {
                cons.take(i);
                for j in i..consumed_to {
                    cons.take(j);
                }
                if let Some(r) = reported {
                    ctx.unexpected.push(r);
                    continue;
                }
                match val {
                    Some(v) => match v.parse::<usize>() {
                        Ok(n) => ctx.opts.fixed_memory = Some(n),
                        Err(e) => {
                            return Err(format!("failed to parse '{}': {}", v, e_message(&e)))
                        }
                    },
                    None => {
                        return Err(format!(
                            "the '{}' option doesn't have an associated value",
                            display_name(i, args, *name, *short)
                        ))
                    }
                }
            }
            continue;
        }
        if let Some((i, val, consumed_to, reported)) = find_option(args, &mut cons, *name, *short, true)
        {
            cons.take(i);
            for j in i..consumed_to {
                cons.take(j);
            }
            if let Some(r) = reported {
                ctx.unexpected.push(r);
                continue;
            }
            match (field, val) {
                (Some(f), Some(v)) => ctx.set_str(*f, v)?,
                (Some(_), None) => {
                    return Err(format!(
                        "the '{}' option doesn't have an associated value",
                        display_name(i, args, *name, *short)
                    ))
                }
                _ => {}
            }
        }
    }

    // flags
    for (name, short) in FLAG_OPTS {
        if let Some((i, _val, consumed_to, reported)) =
            find_option(args, &mut cons, name, Some(*short), false)
        {
            cons.take(i);
            for j in i..consumed_to {
                cons.take(j);
            }
            match reported {
                Some(r) => ctx.unexpected.push(r),
                None => match *name {
                    "greedy-delimiter" => ctx.opts.greedy = true,
                    "compress-delimiter" => ctx.opts.compress = true,
                    "only-delimited" => ctx.opts.only_delimited = true,
                    "zero-terminated" => ctx.opts.zero_terminated = true,
                    "complement" => ctx.opts.complement = true,
                    "join" => ctx.opts.join = true,
                    _ => {}
                },
            }
        }
    }
    if let Some((i, _val, consumed_to, reported)) =
        find_option(args, &mut cons, "json", None, false)
    {
        cons.take(i);
        for j in i..consumed_to {
            cons.take(j);
        }
        match reported {
            Some(r) => ctx.unexpected.push(r),
            None => ctx.opts.json = true,
        }
    }
    if let Some((i, _val, consumed_to, reported)) =
        find_option(args, &mut cons, "no-mmap", None, false)
    {
        cons.take(i);
        for j in i..consumed_to {
            cons.take(j);
        }
        match reported {
            Some(r) => ctx.unexpected.push(r),
            None => ctx.opts.no_mmap = true,
        }
    }
    if let Some((i, _val, consumed_to, reported)) =
        find_option(args, &mut cons, "no-join", None, false)
    {
        cons.take(i);
        for j in i..consumed_to {
            cons.take(j);
        }
        match reported {
            Some(r) => ctx.unexpected.push(r),
            None => ctx.opts.join = false,
        }
    }

