//! Command line parsing.
//!
//! Options are searched in a fixed order and each of them is consumed at most
//! once. Whatever is left over is reported as an unexpected argument, exactly
//! like the original tool does.

use crate::help;

/// `--trim` values.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Trim {
    Left,
    Right,
    Both,
}

/// The delimiter used to cut a line.
#[derive(Clone, Debug)]
pub enum Delim {
    /// A plain string.
    Str(Vec<u8>),
    /// A regular expression.
    Regex(regex::Regex),
}

/// Which kind of cutting is requested.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Mode {
    Fields,
    Bytes,
    Characters,
    Lines,
}

/// Everything the tool needs to know about the invocation.
#[derive(Clone, Debug)]
pub struct Options {
    pub mode: Mode,
    pub bounds: Option<String>,
    pub delimiter: String,
    pub regex: Option<String>,
    pub replace: Option<String>,
    pub trim: Option<Trim>,
    pub fallback_oob: Option<String>,
    pub fixed_memory: Option<usize>,
    pub greedy: bool,
    pub compress: bool,
    pub only_delimited: bool,
    pub zero_terminated: bool,
    pub complement: bool,
    pub join: bool,
    pub json: bool,
    pub no_mmap: bool,
    pub file: Option<String>,
}

impl Default for Options {
    fn default() -> Options {
        Options {
            mode: Mode::Fields,
            bounds: None,
            delimiter: "\t".to_string(),
            regex: None,
            replace: None,
            trim: None,
            fallback_oob: None,
            fixed_memory: None,
            greedy: false,
            compress: false,
            only_delimited: false,
            zero_terminated: false,
            complement: false,
            join: false,
            json: false,
            no_mmap: false,
            file: None,
        }
    }
}

/// Short flags that can be clustered together.
const FLAG_CHARS: &[(char, &str)] = &[
    ('g', "greedy-delimiter"),
    ('p', "compress-delimiter"),
    ('s', "only-delimited"),
    ('z', "zero-terminated"),
    ('m', "complement"),
    ('j', "join"),
];

/// Short options that take a value.
const OPT_CHARS: &[(char, &str)] = &[
    ('f', "fields"),
    ('b', "bytes"),
    ('c', "characters"),
    ('l', "lines"),
    ('d', "delimiter"),
    ('e', "regex"),
    ('r', "replace-delimiter"),
    ('t', "trim"),
    ('M', "fixed-memory"),
];

/// Options that take a value, in the order they are looked up.
const VALUE_ORDER: &[(&str, Option<char>)] = &[
    ("fields", Some('f')),
    ("bytes", Some('b')),
    ("characters", Some('c')),
    ("lines", Some('l')),
    ("delimiter", Some('d')),
    ("regex", Some('e')),
    ("replace-delimiter", Some('r')),
    ("trim", Some('t')),
    ("fallback-oob", None),
    ("fixed-memory", Some('M')),
];

/// Boolean flags, in the order they are looked up.
const FLAG_ORDER: &[(&str, Option<char>)] = &[
    ("greedy-delimiter", Some('g')),
    ("compress-delimiter", Some('p')),
    ("only-delimited", Some('s')),
    ("zero-terminated", Some('z')),
    ("complement", Some('m')),
    ("join", Some('j')),
    ("json", None),
    ("no-mmap", None),
    ("no-join", None),
];

fn flag_long(short: char) -> Option<&'static str> {
    FLAG_CHARS
        .iter()
        .find(|(c, _)| *c == short)
        .map(|(_, n)| *n)
}

fn opt_long(short: char) -> Option<&'static str> {
    OPT_CHARS
        .iter()
        .find(|(c, _)| *c == short)
        .map(|(_, n)| *n)
}

pub enum ParseOutcome {
    /// `--help` or `--version` was printed, nothing else to do.
    Done,
    /// The options were parsed successfully.
    Options(Options),
}

fn unexpected(items: &[String]) -> String {
    let mut s = String::from("tuc: unexpected arguments: [");
    for (i, it) in items.iter().enumerate() {
        if i > 0 {
            s.push_str(", ");
        }
        s.push_str(&rust_debug_str(it));
    }
    s.push_str("]\nTry 'tuc --help' for more information.");
    s
}

fn rust_debug_str(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\0' => out.push_str("\\0"),
            c if (c as u32) < 0x20 || c == '\u{7f}' => {
                out.push_str(&format!("\\u{{{:x}}}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Returns true when `args` contains a request for help or version.
fn help_or_version(args: &[String]) -> Option<&'static str> {
    for a in args {
        if a == "--help" || a == "-h" {
            return Some("help");
        }
    }
    for a in args {
        if a == "--version" || a == "-V" {
            return Some("version");
        }
    }
    for a in args {
        if a.starts_with('-') && !a.starts_with("--") && a.len() > 1 {
            for c in a[1..].chars() {
                if c == 'h' {
                    return Some("help");
                }
            }
        }
    }
    for a in args {
        if a.starts_with('-') && !a.starts_with("--") && a.len() > 1 {
            for c in a[1..].chars() {
                if c == 'V' {
                    return Some("version");
                }
            }
        }
    }
    None
}

/// Mutable state used while parsing.
struct P {
    opts: Options,
    used: Vec<bool>,
    unexpected: Vec<String>,
    flags_set: [bool; 6],
}

impl P {
    fn new(n: usize) -> P {
        P {
            opts: Options::default(),
            used: vec![false; n],
            unexpected: Vec::new(),
            flags_set: [false; 6],
        }
    }
    fn free(&self) -> Vec<usize> {
        (0..self.used.len()).filter(|i| !self.used[*i]).collect()
    }
    /// Looks for the next free argument starting at `from`.
    fn next_free(&self, from: usize) -> Option<usize> {
        (from..self.used.len()).find(|i| !self.used[*i])
    }
}

/// The result of matching an option name inside an argument.
struct Match {
    /// index of the argument that carries the option
    idx: usize,
    /// value if it was attached with `=`
    attached: Option<String>,
    /// report of a cluster failure
    report: Option<String>,
}

impl Match {
    fn none() -> Option<Match> {
        None
    }
}

/// Scans the arguments for the first unconsumed occurrence of `name`.
fn scan(
    p: &mut P,
    args: &[String],
    name: &str,
    short: Option<char>,
    takes_value: bool,
) -> Option<(usize, Option<String>, Option<String>)> {
    for i in 0..args.len() {
        if p.used[i] {
            continue;
        }
        let a = &args[i];
        if a.starts_with("--") {
            let body = &a[2..];
            if let Some(eq) = body.find('=') {
                if &body[..eq] == name {
                    if takes_value {
                        p.used[i] = true;
                        return Some((i, Some(body[eq + 1..].to_string()), None));
                    }
                    // flags never accept a value
                    p.used[i] = true;
                    return Some((i, None, Some(a.clone())));
                }
            } else if body == name {
                p.used[i] = true;
                if takes_value {
                    let v = p
                        .next_free(i + 1)
                        .map(|j| {
                            p.used[j] = true;
                            args[j].clone()
                        });
                    return Some((i, v, None));
                }
                return Some((i, None, None));
            }
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            if let Some(sc) = short {
                let chars: Vec<char> = a[1..].chars().collect();
                if chars[0] == sc {
                    p.used[i] = true;
                    if takes_value {
                        let rest: String = chars[1..].iter().collect();
                        if rest.is_empty() {
                            let v = p
                                .next_free(i + 1)
                                .map(|j| {
                                    p.used[j] = true;
                                    args[j].clone()
                                });
                            return Some((i, v, None));
                        }
                        let rest = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                        return Some((i, Some(rest), None));
                    }
                    let report = run_cluster(p, &chars, 0);
                    return Some((i, None, report));
                }
            }
            // a flag can also appear deeper in a cluster
            if !takes_value {
                if let Some(sc) = short {
                    let chars: Vec<char> = a[1..].chars().collect();
                    for k in 1..chars.len() {
                        if chars[k] == sc {
                            let report = run_cluster(p, &chars, k);
                            return Some((i, None, report));
                        }
                    }
                }
            }
        }
    }
    None
}

/// Processes a short option cluster. Flags that have not been seen before are
/// removed from the report, everything else stays.
fn run_cluster(p: &mut P, chars: &[char], from: usize) -> Option<String> {
    // help and version short circuit before anything else
    for c in chars {
        if *c == 'h' {
            print!("{}", crate::help::colored_help());
            std::process::exit(0);
        }
        if *c == 'V' {
            print!("{}", crate::help::VERSION);
            std::process::exit(0);
        }
    }
    let mut kept: Vec<char> = Vec::new();
    let mut failed = false;
    for (k, c) in chars.iter().enumerate().skip(from) {
        if failed {
            kept.push(*c);
            continue;
        }
        if let Some(long) = flag_long(*c) {
            let idx = FLAG_CHARS.iter().position(|(x, _)| *x == *c).unwrap();
            if p.flags_set[idx] {
                kept.push(*c);
                failed = true;
                continue;
            }
            p.flags_set[idx] = true;
            match long {
                "greedy-delimiter" => p.opts.greedy = true,
                "compress-delimiter" => p.opts.compress = true,
                "only-delimited" => p.opts.only_delimited = true,
                "zero-terminated" => p.opts.zero_terminated = true,
                "complement" => p.opts.complement = true,
                "join" => p.opts.join = true,
                _ => {}
            }
            continue;
        }
        // either a value taking option or an unknown flag: both are reported
        kept.push(*c);
        failed = true;
    }
    if kept.is_empty() {
        None
    } else {
        let s: String = kept.iter().collect();
        Some(format!("-{}", s))
    }
}

pub fn parse(args: &[String]) -> Result<ParseOutcome, String> {
    if let Some(which) = help_or_version(args) {
        if which == "help" {
            print!("{}", crate::help::colored_help());
        } else {
            print!("{}", crate::help::VERSION);
        }
        return Ok(ParseOutcome::Done);
    }
    let mut p = P::new(args.len());

    for (name, short) in VALUE_ORDER {
        match scan(&mut p, args, name, *short, true) {
            Some((_i, value, report)) => {
                if let Some(r) = report {
                    p.unexpected.push(r);
                    continue;
                }
                let v = match value {
                    Some(v) => v,
                    None => {
                        return Err(format!(
                            "the '{}' option doesn't have an associated value",
                            option_display(name, *short)
                        ))
                    }
                };
                match *name {
                    "fields" | "bytes" | "characters" | "lines" => {
                        p.opts.bounds = Some(v);
                        p.opts.mode = match *name {
                            "bytes" => Mode::Bytes,
                            "characters" => Mode::Characters,
                            "lines" => Mode::Lines,
                            _ => Mode::Fields,
                        };
                    }
                    "delimiter" => p.opts.delimiter = v,
                    "regex" => p.opts.regex = Some(v),
                    "replace-delimiter" => {
                        p.opts.replace = Some(v);
                        p.opts.join = true;
                    }
                    "trim" => {
                        let t = match v.as_str() {
                            "l" | "L" => Trim::Left,
                            "r" | "R" => Trim::Right,
                            "b" | "B" => Trim::Both,
                            _ => {
                                return Err(format!(
                                    "failed to parse '{}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth",
                                    v
                                ))
                            }
                        };
                        p.opts.trim = Some(t);
                    }
                    "fallback-oob" => p.opts.fallback_oob = Some(v),
                    "fixed-memory" => match v.parse::<usize>() {
                        Ok(n) => p.opts.fixed_memory = Some(n),
                        Err(e) => return Err(format!("failed to parse '{}': {}", v, e)),
                    },
                    _ => {}
                }
            }
            None => {}
        }
    }

    for (name, short) in FLAG_ORDER {
        match scan(&mut p, args, name, *short, false) {
            Some((_i, _value, report)) => {
                if let Some(r) = report {
                    p.unexpected.push(r);
                    continue;
                }
                match *name {
                    "greedy-delimiter" => p.opts.greedy = true,
                    "compress-delimiter" => p.opts.compress = true,
                    "only-delimited" => p.opts.only_delimited = true,
                    "zero-terminated" => p.opts.zero_terminated = true,
                    "complement" => p.opts.complement = true,
                    "join" => p.opts.join = true,
                    "json" => p.opts.json = true,
                    "no-mmap" => p.opts.no_mmap = true,
                    "no-join" => p.opts.join = false,
                    _ => {}
                }
            }
            None => {}
        }
    }

    let free = p.free();
    if free.len() > 1 {
        let items: Vec<String> = free.iter().map(|i| args[*i].clone()).collect();
        return Err(unexpected(&items));
    }
    if free.len() == 1 {
        p.opts.file = Some(args[free[0]].clone());
    }
    if !p.unexpected.is_empty() {
        return Err(unexpected(&p.unexpected));
    }
    Ok(ParseOutcome::Options(p.opts))
}

fn option_display(name: &str, short: Option<char>) -> String {
