            if !takes_value {
                if let Some(sc) = short {
                    let chars: Vec<char> = a[1..].chars().collect();
                    for k in 1..chars.len() {
                        if chars[k] == sc {
                            let report = run_cluster(p, &chars, k);
                            return Some((i, None, report));
                        }
                    }
                }
            }
        }
    }
    None
}

/// Processes a short option cluster. Flags that have not been seen before are
/// removed from the report, everything else stays.
fn run_cluster(p: &mut P, chars: &[char], from: usize) -> Option<String> {
    // help and version short circuit before anything else
    for c in chars {
        if *c == 'h' {
            print!("{}", crate::help::colored_help());
            std::process::exit(0);
        }
        if *c == 'V' {
            print!("{}", crate::help::VERSION);
            std::process::exit(0);
        }
    }
    let mut kept: Vec<char> = Vec::new();
    let mut failed = false;
    for (k, c) in chars.iter().enumerate().skip(from) {
        if failed {
            kept.push(*c);
            continue;
        }
        if let Some(long) = flag_long(*c) {
            let idx = FLAG_CHARS.iter().position(|(x, _)| *x == *c).unwrap();
            if p.flags_set[idx] {
                kept.push(*c);
                failed = true;
                continue;
            }
            p.flags_set[idx] = true;
            match long {
                "greedy-delimiter" => p.opts.greedy = true,
                "compress-delimiter" => p.opts.compress = true,
                "only-delimited" => p.opts.only_delimited = true,
                "zero-terminated" => p.opts.zero_terminated = true,
                "complement" => p.opts.complement = true,
                "join" => p.opts.join = true,
                _ => {}
            }
            continue;
        }
        // either a value taking option or an unknown flag: both are reported
        kept.push(*c);
        failed = true;
    }
    if kept.is_empty() {
        None
    } else {
        let s: String = kept.iter().collect();
        Some(format!("-{}", s))
    }
}

pub fn parse(args: &[String]) -> Result<ParseOutcome, String> {
    if let Some(which) = help_or_version(args) {
        if which == "help" {
            print!("{}", crate::help::colored_help());
        } else {
            print!("{}", crate::help::VERSION);
        }
        return Ok(ParseOutcome::Done);
    }
    let mut p = P::new(args.len());

    for (name, short) in VALUE_ORDER {
        match scan(&mut p, args, name, *short, true) {
            Some((_i, value, report)) => {
                if let Some(r) = report {
                    p.unexpected.push(r);
                    continue;
                }
                let v = match value {
                    Some(v) => v,
                    None => {
                        return Err(format!(
                            "the '{}' option doesn't have an associated value",
                            option_display(name, *short)
                        ))
                    }
                };
                match *name {
                    "fields" | "bytes" | "characters" | "lines" => {
                        p.opts.bounds = Some(v);
                        p.opts.mode = match *name {
                            "bytes" => Mode::Bytes,
                            "characters" => Mode::Characters,
                            "lines" => Mode::Lines,
                            _ => Mode::Fields,
                        };
                    }
                    "delimiter" => p.opts.delimiter = v,
                    "regex" => p.opts.regex = Some(v),
                    "replace-delimiter" => {
                        p.opts.replace = Some(v);
                        p.opts.join = true;
                    }
                    "trim" => {
                        let t = match v.as_str() {
                            "l" | "L" => Trim::Left,
                            "r" | "R" => Trim::Right,
                            "b" | "B" => Trim::Both,
                            _ => {
                                return Err(format!(
                                    "failed to parse '{}': Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth",
                                    v
                                ))
                            }
                        };
                        p.opts.trim = Some(t);
                    }
                    "fallback-oob" => p.opts.fallback_oob = Some(v),
                    "fixed-memory" => match v.parse::<usize>() {
                        Ok(n) => p.opts.fixed_memory = Some(n),
                        Err(e) => return Err(format!("failed to parse '{}': {}", v, e)),
                    },
                    _ => {}
                }
            }
            None => {}
        }
    }

    for (name, short) in FLAG_ORDER {
        match scan(&mut p, args, name, *short, false) {
            Some((_i, _value, report)) => {
                if let Some(r) = report {
                    p.unexpected.push(r);
                    continue;
                }
                match *name {
                    "greedy-delimiter" => p.opts.greedy = true,
                    "compress-delimiter" => p.opts.compress = true,
                    "only-delimited" => p.opts.only_delimited = true,
                    "zero-terminated" => p.opts.zero_terminated = true,
                    "complement" => p.opts.complement = true,
                    "join" => p.opts.join = true,
                    "json" => p.opts.json = true,
                    "no-mmap" => p.opts.no_mmap = true,
                    "no-join" => p.opts.join = false,
                    _ => {}
                }
            }
            None => {}
        }
    }

    let free = p.free();
    if free.len() > 1 {
        let items: Vec<String> = free.iter().map(|i| args[*i].clone()).collect();
        return Err(unexpected(&items));
    }
    if free.len() == 1 {
        p.opts.file = Some(args[free[0]].clone());
    }
    if !p.unexpected.is_empty() {
        return Err(unexpected(&p.unexpected));
    }
    Ok(ParseOutcome::Options(p.opts))
}

fn option_display(name: &str, short: Option<char>) -> String {
    match short {
        Some(c) => format!("-{}", c),
        None => format!("--{}", name),
    }
}
