//! Cutting of strings: fields, characters and lines.
//!
//! The input is read line by line and cut with a delimiter which is either a
//! plain string or a regular expression. The bounds given by the user describe
//! which fields to keep and in which order.

use crate::args::{Delim, Mode, Options, Trim};
use crate::bounds::userboundslist::{FormatPart, UserBounds, UserBoundsList};
use crate::reader::{Input, LineReader};
use std::io::Write;

/// Byte ranges of the fields of `line`, given the delimiter occurrences.
pub fn field_ranges(line_len: usize, matches: &[(usize, usize)]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    if line_len == 0 {
        out.push((0, 0));
        return out;
    }
    let mut prev = 0usize;
    for (s, e) in matches {
        out.push((prev, *s));
        prev = *e;
    }
    out.push((prev, line_len));
    out
}

/// Byte ranges of the delimiter occurrences inside `line`.
pub fn find_matches(line: &[u8], delim: &Delim, greedy: bool) -> Vec<(usize, usize)> {
    let mut out: Vec<(usize, usize)> = Vec::new();
    match delim {
        Delim::Str(d) => {
            if d.is_empty() {
                let mut i = 0usize;
                while i < line.len() {
                    out.push((i, i));
                    i += 1;
                }
                if !line.is_empty() {
                    out.push((line.len(), line.len()));
                }
                return out;
            }
            let mut i = 0usize;
            while i + d.len() <= line.len() {
                if &line[i..i + d.len()] == d.as_slice() {
                    if greedy && !out.is_empty() && out.last().unwrap().1 == i {
                        let last = out.last_mut().unwrap();
                        last.1 = i + d.len();
                    } else {
                        out.push((i, i + d.len()));
                    }
                    i += d.len();
                } else {
                    i += 1;
                }
            }
        }
        Delim::Regex(re) => {
            let hay = String::from_utf_lossy(line);
            for m in re.find_iter(&hay) {
                let (st, en) = (m.start(), m.end());
                if greedy && !out.is_empty() && out.last().unwrap().1 == st {
                    let last = out.last_mut().unwrap();
                    last.1 = en;
                } else {
                    out.push((st, en));
                }
            }
        }
    }
    out
}

/// `--compress-delimiter`: consecutive delimiters are printed only once.
pub fn compress(line: &[u8], delim: &Delim) -> Vec<u8> {
    match delim {
        Delim::Str(d) => {
            if d.is_empty() {
                return line.to_vec();
            }
            let mut out: Vec<u8> = Vec::new();
            let mut i = 0usize;
            let mut run = false;
            while i < line.len() {
                if i + d.len() <= line.len() && &line[i..i + d.len()] == d.as_slice() {
                    if !run {
                        out.extend_from_slice(d);
                        run = true;
                    }
                    i += d.len();
                    continue;
                }
                out.push(line[i]);
                run = false;
                i += 1;
            }
            out
        }
        Delim::Regex(_) => line.to_vec(),
    }
}

/// `--trim`: the delimiters at the border of the line are removed.
pub fn trim_line(line: &[u8], delim: &Delim, side: &Trim) -> Vec<u8> {
    let d: Vec<u8> = match delim {
        Delim::Str(d) => d.clone(),
        Delim::Regex(_) => Vec::new(),
    };
    if d.is_empty() {
        // a zero width delimiter never stops matching; the original tool
        // loops forever in this situation and we reproduce that.
        loop {
            std::thread::yield_now();
        }
    }
    let mut v = line.to_vec();
    let left = matches!(side, Trim::Left) || matches!(side, Trim::Both);
    let right = matches!(side, Trim::Right) || matches!(side, Trim::Both);
    if left {
        while v.len() >= d.len() && &v[..d.len()] == d.as_slice() {
            v.drain(..d.len());
        }
    }
    if right {
        while v.len() >= d.len() && &v[v.len() - d.len()..] == d.as_slice() {
            v.truncate(v.len() - d.len());
        }
    }
    v
}

/// Text of a single field.
pub fn field_text(line: &[u8], r: (usize, usize)) -> &[u8] {
    &line[r.0..r.1]
}

/// Text spanning several fields, delimiters included.
pub fn range_text(line: &[u8], start: (usize, usize), end: (usize, usize)) -> &[u8] {
    &line[start.0..end.1]
}

/// True when `line` contains the delimiter at least once.
pub fn line_is_delimited(line: &[u8], delim: &Delim) -> bool {
    match delim {
        Delim::Str(d) => {
            if d.is_empty() {
                false
            } else {
                line.windows(d.len()).any(|w| w == d.as_slice())
            }
        }
        Delim::Regex(re) => {
            let hay = String::from_utf_lossy(line);
            re.find_iter(&hay)
                .next()
                .map(|m| m.end() > m.start())
                .unwrap_or(false)
        }
    }
}

/// Convert a line of bytes to a `&str` when it is valid utf-8.
pub fn as_str(line: &[u8]) -> Option<&str> {
    std::str::from_utf8(line).ok()
}

/// Number of characters of a line; invalid utf-8 is counted byte wise.
pub fn char_len(line: &[u8]) -> usize {
    match std::str::from_utf8(line) {
        Ok(s) => s.chars().count(),
        Err(_) => line.len(),
    }
}

/// Byte ranges of every character of the line.
pub fn char_offsets(line: &[u8]) -> Vec<(usize, usize)> {
    match std::str::from_utf8(line) {
        Ok(s) => s
            .char_indices()
            .map(|(i, c)| (i, i + c.len_utf8()))
            .collect(),
        Err(_) => (0..line.len()).map(|i| (i, i + 1)).collect(),
    }
}

/// Resolve a (possibly negative) 1 indexed position.
pub fn resolve_index(idx: i64, n: usize) -> Option<usize> {
    if idx > 0 {
        if (idx as usize) <= n {
            Some(idx as usize)
        } else {
            None
        }
    } else {
        let off = (-idx) as usize;
        if off <= n {
            Some(n - off + 1)
        } else {
            None
        }
    }
}

/// One piece of the output of a single line.
pub enum OutPart {
    /// literal text, coming from a fallback value or from a format string
    Literal(Vec<u8>),
    /// a field, or a run of fields including the delimiters in between
    Field(usize, usize),
}

/// Resolves the user bounds against the fields of a line. `counted` tells
/// whether the extract function in use is able to count the fields; when it
/// cannot and the count would be required the tool panics, exactly like the
/// original implementation does.
pub fn resolve_bounds(
    list: &UserBoundsList,
    ranges: &[(usize, usize)],
    lines_mode: bool,
    only_delimited: bool,
) -> Result<Vec<OutPart>, String> {
    let n = ranges.len();
    let mut out: Vec<OutPart> = Vec::new();
    for b in &list.bounds {
        match b {
            UserBounds::Single { idx, fallback } => match resolve_index(*idx, n) {
                Some(i) => out.push(OutPart::Field(ranges[i - 1].0, ranges[i - 1].1)),
                None => {
                    if let Some(f) = fallback {
                        out.push(OutPart::Literal(f.as_bytes().to_vec()));
                        continue;
                    }
                    if list.fallback_oob.is_some() {
                        out.push(OutPart::Literal(Vec::new()));
                        continue;
                    }
                    if lines_mode {
                        if bounds_are_one(&list.bounds) {
                            return Err("the complement is empty".to_string());
                        }
                        if only_delimited {
                            panic_count_only_delimited();
                        }
                        panic_count_generic();
                    }
                    return Err(format!("Out of bounds: {}", idx));
                }
            },
            UserBounds::Range { start, end, fallback } => {
                let s = match resolve_index(*start, n) {
                    Some(s) => s,
                    None => {
                        if let Some(f) = fallback {
                            out.push(OutPart::Literal(f.as_bytes().to_vec()));
                            continue;
                        }
                        if list.fallback_oob.is_some() {
                            out.push(OutPart::Literal(Vec::new()));
                            continue;
                        }
                        return Err(format!("Out of bounds: {}", start));
                    }
                };
                let e = match resolve_index(*end, n) {
                    Some(e) => e,
                    None => {
                        if lines_mode || only_delimited {
                            if only_delimited {
                                panic_count_only_delimited();
                            }
                            panic_count_generic();
                        }
                        n
                    }
                };
                out.push(OutPart::Field(ranges[s - 1].0, ranges[e - 1].1));
            }
        }
    }
    Ok(out)
}

fn bounds_are_one(bounds: &[UserBounds]) -> bool {
    bounds.iter().all(|b| match b {
        UserBounds::Single { idx, .. } => *idx == 1,
        UserBounds::Range { start, end, .. } => *start == 1 && (*end == 1 || *end == i64::MAX),
    })
}
