/// One piece of the output of a single line.
pub enum OutPart {
    /// literal text, from a fallback value or from a format string
    Literal(Vec<u8>),
    /// a field, or a run of fields including the delimiters in between
    Field(usize, usize),
}

/// Resolves the user bounds against the fields of a line.
pub fn resolve_bounds(
    list: &UserBoundsList,
    ranges: &[(usize, usize)],
    lines_mode: bool,
    only_delimited: bool,
    empty_is_error: bool,
) -> Result<Vec<OutPart>, String> {
    let n = ranges.len();
    let mut out: Vec<OutPart> = Vec::new();
    for b in &list.bounds {
        match b {
            UserBounds::Single { idx, fallback } => match resolve_index(*idx, n) {
                Some(i) => out.push(OutPart::Field(ranges[i - 1].0, ranges[i - 1].1)),
                None => {
                    if let Some(f) = fallback {
                        out.push(OutPart::Literal(f.as_bytes().to_vec()));
                        continue;
                    }
                    if list.fallback_oob.is_some() {
                        out.push(OutPart::Literal(list.fallback_oob_value()));
                        continue;
                    }
                    if lines_mode || only_delimited {
                        if empty_is_error && bounds_are_one(&list.bounds) {
                            return Err("the complement is empty".to_string());
                        }
                        if only_delimited {
                            panic_count_only_delimited();
                        }
                        panic_count_generic();
                    }
                    return Err(format!("Out of bounds: {}", idx));
                }
            },
            UserBounds::Range { start, end, fallback } => {
                let s = match resolve_index(*start, n) {
                    Some(s) => s,
                    None => {
                        if let Some(f) = fallback {
                            out.push(OutPart::Literal(f.as_bytes().to_vec()));
                            continue;
                        }
                        if list.fallback_oob.is_some() {
                            out.push(OutPart::Literal(list.fallback_oob_value()));
                            continue;
                        }
                        if only_delimited {
                            panic_count_only_delimited();
                        }
                        if lines_mode || list.needs_count() {
                            panic_count_generic();
                        }
                        return Err(format!("Out of bounds: {}", start));
                    }
                };
                let e = match resolve_index(*end, n) {
                    Some(e) => e,
                    None => {
                        if list.needs_count() || lines_mode {
                            if only_delimited {
                                panic_count_only_delimited();
                            }
                            panic_count_generic();
                        }
                        n
                    }
                };
                out.push(OutPart::Field(ranges[s - 1].0, ranges[e - 1].1));
            }
        }
    }
    if out.is_empty() {
        return Err("the complement is empty".to_string());
    }
    Ok(out)
}

fn bounds_are_one(bounds: &[UserBounds]) -> bool {
    bounds.iter().all(|b| match b {
        UserBounds::Single { idx, .. } => *idx == 1,
        UserBounds::Range { start, end, .. } => *start == 1 && (*end == 1 || *end == i64::MAX),
    })
}

/// The complement of the selection: for every bound the fields around it are
/// selected instead.
pub fn complement(
    list: &UserBoundsList,
    ranges: &[(usize, usize)],
    only_delimited: bool,
    empty_is_error: bool,
) -> Result<Vec<OutPart>, String> {
    let n = ranges.len();
    let mut out: Vec<OutPart> = Vec::new();
    for b in &list.bounds {
        let (start, end) = match b {
            UserBounds::Single { idx, .. } => match resolve_index(*idx, n) {
                Some(i) => (i as i64, i as i64),
                None => {
                    if list.fallback_oob.is_some() {
                        out.push(OutPart::Literal(list.fallback_oob_value()));
                        continue;
                    }
                    if empty_is_error && bounds_are_one(&list.bounds) {
                        return Err("the complement is empty".to_string());
                    }
                    if only_delimited {
                        panic_count_only_delimited();
                    }
                    panic_count_generic();
                }
            },
            UserBounds::Range { start, end, .. } => {
                let s = match resolve_index(*start, n) {
                    Some(s) => s as i64,
                    None => {
                        if list.fallback_oob.is_some() {
                            out.push(OutPart::Literal(list.fallback_oob_value()));
                            continue;
                        }
                        if empty_is_error && bounds_are_one(&list.bounds) {
                            return Err("the complement is empty".to_string());
                        }
                        if only_delimited {
                            panic_count_only_delimited();
                        }
                        panic_count_generic();
                    }
                };
                let e = match resolve_index(*end, n) {
                    Some(e) => e as i64,
                    None => n as i64,
                };
                (s, e)
            }
        };
        if start > 1 {
            let last = (start - 1) as usize;
            out.push(OutPart::Field(ranges[0].0, ranges[last - 1].1));
        }
        if (end as usize) < n {
            let first = end as usize;
            out.push(OutPart::Field(ranges[first].0, ranges[n - 1].1));
        }
    }
    if out.is_empty() {
        return Err("the complement is empty".to_string());
    }
    Ok(out)
}

/// Escapes a string for json output.
pub fn json_escape(line: &[u8], r: (usize, usize)) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.push(b'"');
    let s = &line[r.0..r.1];
    let text = String::from_utf_lossy(s);
    for c in text.chars() {
        match c {
            '"' => out.extend_from_slice(b"\\\""),
            '\\' => out.extend_from_slice(b"\\\\"),
            '\n' => out.extend_from_slice(b"\\n"),
            '\r' => out.extend_from_slice(b"\\r"),
            '\t' => out.extend_from_slice(b"\\t"),
            '\u{8}' => out.extend_from_slice(b"\\b"),
            '\u{c}' => out.extend_from_slice(b"\\f"),
            c if (c as u32) < 0x20 => {
                out.extend_from_slice(format!("\\u{:04x}", c as u32).as_bytes())
            }
            c => {
                let mut buf = [0u8; 4];
                out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes())
            }
        }
    }
    out.push(b'"');
    out
}

/// Builds the output of one line from the resolved parts.
pub fn render(
    line: &[u8],
    list: &UserBoundsList,
    parts: &[OutPart],
    delim: &Delim,
    join: bool,
    replace: Option<&[u8]>,
    json: bool,
) -> Result<Vec<u8>, String> {
    if json {
        if list.parts.iter().any(|p| matches!(p, FormatPart::Literal(_))) {
            return Err(
                "tuc: runtime error. Cannot format fields when using --json".to_string(),
            );
        }
        let mut buf: Vec<u8> = Vec::new();
        buf.push(b'[');
        let bounds_parts: Vec<usize> = list
            .parts
            .iter()
            .filter_map(|p| match p {
                FormatPart::Bounds(i) => Some(*i),
                _ => None,
            })
            .collect();
        let m = bounds_parts.len();
        let delim_empty = matches!(delim, Delim::Str(d) if d.is_empty());
        for (k, bi) in bounds_parts.iter().enumerate() {
            if k > 0 {
                buf.push(b',');
            }
            let part = match parts.get(*bi) {
                Some(p) => p,
                None => continue,
            };
            if delim_empty {
                // an empty delimiter makes the wrapping of the elements
                // visible: the delimiter of the neighbours is printed too
                if k > 0 {
                    buf.extend_from_slice(b",");
                }
                match part {
                    OutPart::Literal(v) => buf.extend_from_slice(v),
                    OutPart::Field(s, e) => buf.extend_from_slice(&line[*s..*e]),
                }
                if k + 1 < m {
                    buf.extend_from_slice(b",");
                }
            } else {
                match part {
                    OutPart::Literal(v) => buf.extend_from_slice(v),
                    OutPart::Field(s, e) => buf.extend_from_slice(json_escape(line, (*s, *e))),
                }
            }
        }
        buf.push(b']');
        return Ok(buf);
    }
    let mut buf: Vec<u8> = Vec::new();
    let bounds_idx: Vec<usize> = list
        .parts
        .iter()
        .filter_map(|p| match p {
            FormatPart::Bounds(i) => Some(*i),
            _ => None,
        })
        .collect();
    let has_bounds_after = |k: usize| bounds_idx[k + 1..].iter().any(|_| true);
    for (i, part) in list.parts.iter().enumerate() {
        match part {
            FormatPart::Literal(s) => buf.extend_from_slice(s.as_bytes()),
            FormatPart::Bounds(idx) => {
                match parts.get(*idx) {
                    Some(OutPart::Literal(v)) => buf.extend_from_slice(v),
                    Some(OutPart::Field(s, e)) => buf.extend_from_slice(&line[*s..*e]),
                    None => {}
                }
                if join && i + 1 < list.parts.len() {
                    // a delimiter is printed when another bound follows
                    if list
                        .parts
                        .iter()
                        .skip(i + 1)
                        .any(|p| matches!(p, FormatPart::Bounds(_)))
                        && has_bounds_after(bounds_idx.iter().position(|x| *x == *idx).unwrap())
                    {
                        match replace {
                            Some(r) => buf.extend_from_slice(r),
                            None => match delim {
                                Delim::Str(d) => buf.extend_from_slice(d),
                                Delim::Regex(_) => {}
                            },
                        }
                    }
                }
            }
        }
    }
    Ok(buf)
}

fn delimiter_of(opts: &Options) -> Result<Delim, String> {
    match &opts.regex {
        Some(pattern) => match regex::Regex::new(pattern) {
            Ok(re) => Ok(Delim::Regex(re)),
            Err(e) => Err(format!(
                "tuc: runtime error. The regular expression is malformed. {}",
                e
            )),
        },
        None => Ok(Delim::Str(opts.delimiter.clone().into_bytes())),
    }
}

/// Runs the string based modes: fields, characters and lines.
pub fn run(input: Input, opts: &Options, out: &mut dyn Write) -> Result<(), String> {
    let delim = delimiter_of(opts)?;
    let sep: u8 = if opts.zero_terminated { 0 } else { b'\n' };
    if opts.mode == Mode::Lines {
        return run_lines(input, opts, out);
    }
    let mut reader = LineReader::new(input, sep);
    while let Some((line, _has_sep)) = reader.next_line() {
        let mut content = line;
        if sep == b'\n' && content.last() == Some(&b'\r') {
            content.pop();
        }
        if opts.only_delimited && !line_is_delimited(&content, &delim) {
            continue;
        }
        let mut content = content;
        if let Some(t) = opts.trim {
            content = trim_line(&content, &delim, &t);
        }
        if opts.compress {
            content = compress(&content, &delim);
        }
        let ranges = match opts.mode {
            Mode::Characters => char_offsets(&content),
            _ => {
                let matches = find_matches(&content, &delim, opts.greedy);
                field_ranges(content.len(), &matches)
            }
        };
        let list = UserBoundsList::parse(opts.bounds.as_deref().unwrap_or("1:"))?;
        let parts = if opts.complement {
            complement(
                &list,
                &ranges,
                opts.only_delimited,
                opts.mode == Mode::Fields,
            )?
        } else {
            resolve_bounds(
                &list,
                &ranges,
                false,
                opts.only_delimited,
                opts.mode == Mode::Fields,
            )?
        };
        let rendered = render(
            &content,
            &list,
            &parts,
            &delim,
            opts.join || opts.mode == Mode::Characters,
            opts.replace.as_deref().map(|s| s.as_bytes()),
            opts.json,
        )?;
        out.write_all(&rendered).map_err(|e| e.to_string())?;
        out.write_all(&[sep]).map_err(|e| e.to_string())?;
    }
    Ok(())
}

/// The `--lines` mode: the whole input is one line and its fields are lines.
fn run_lines(input: Input, opts: &Options, out: &mut dyn Write) -> Result<(), String> {
    let data = input.bytes().to_vec();
    if String::from_utf8(data.clone()).is_err() {
        return Err("Error: stream did not contain valid UTF-8".to_string());
    }
    let sep: u8 = if opts.zero_terminated { 0 } else { b'\n' };
    // split into lines, keeping whether a separator terminated them
    let mut lines: Vec<Vec<u8>> = Vec::new();
    let mut had_sep: Vec<bool> = Vec::new();
    {
        let mut pos = 0usize;
        while pos < data.len() {
            match data[pos..].iter().position(|c| *c == sep) {
                Some(i) => {
                    lines.push(data[pos..pos + i].to_vec());
                    had_sep.push(true);
                    pos += i + 1;
                }
                None => {
                    lines.push(data[pos..].to_vec());
                    had_sep.push(false);
                    pos = data.len();
                }
            }
        }
    }
    let delim = Delim::Str(vec![sep]);
    let ranges: Vec<(usize, usize)> = lines
        .iter()
        .scan(0usize, |acc, l| {
            let s = *acc;
            *acc += l.len();
            Some((s, s + l.len()))
        })
        .collect();
    if opts.only_delimited && !opts.greedy && !opts.compress {
        // only lines containing the delimiter are printed
        let mut keep: Vec<(usize, usize)> = Vec::new();
        let mut idx: Vec<usize> = Vec::new();
        for (i, l) in lines.iter().enumerate() {
            if line_is_delimited(l, &crate::args::Delim::Str(opts.delimiter.clone().into_bytes()))
            {
                keep.push(ranges[i]);
                idx.push(i);
            }
        }
        let list = UserBoundsList::parse(opts.bounds.as_deref().unwrap_or("1:"))?;
        let parts = resolve_bounds(&list, &keep, true, true, true)?;
        let mut buf: Vec<u8> = Vec::new();
        for p in &parts {
            if let OutPart::Field(s, e) = p {
                buf.extend_from_slice(&data[*s..*e]);
                if *e <= data.len() && data[*s..*e].last() != Some(&sep) {
                    buf.push(sep);
                }
            }
        }
        if buf.is_empty() {
            return Ok(());
        }
        if buf.last() != Some(&sep) {
            buf.push(sep);
        }
        out.write_all(&buf).map_err(|e| e.to_string())?;
        return Ok(());
    }
    let list = UserBoundsList::parse(opts.bounds.as_deref().unwrap_or("1:"))?;
    let parts = if opts.complement {
        complement(&list, &ranges, opts.only_delimited, true)?
    } else {
        resolve_bounds(&list, &ranges, true, opts.only_delimited, true)?
    };
    let join = if opts.complement || opts.only_delimited || opts.compress {
        true
    } else {
        opts.join
    };
    let mut buf: Vec<u8> = Vec::new();
    for (k, p) in parts.iter().enumerate() {
        match p {
            OutPart::Literal(v) => buf.extend_from_slice(v),
            OutPart::Field(s, e) => {
                buf.extend_from_slice(&data[*s..*e]);
                if join && had_sep[*s..].iter().position(|x| true).is_some() {
                    // separator kept below
                }
            }
        }
        let _ = k;
    }
    let _ = delim;
    let mut finalised: Vec<u8> = Vec::new();
    if join {
        for p in &parts {
            match p {
                OutPart::Literal(v) => finalised.extend_from_slice(v),
                OutPart::Field(s, e) => {
                    finalised.extend_from_slice(&data[*s..*e]);
                    if had_sep[*s] {
                        finalised.push(sep);
                    }
                }
            }
        }
        if finalised.last() != Some(&sep) {
            finalised.push(sep);
        }
    } else {
        for p in &parts {
            match p {
                OutPart::Literal(v) => finalised.extend_from_slice(v),
                OutPart::Field(s, e) => finalised.extend_from_slice(&data[*s..*e]),
            }
        }
        if finalised.last() != Some(&sep) {
            finalised.push(sep);
        }
    }
    out.write_all(&finalised).map_err(|e| e.to_string())?;
    Ok(())
}
