//! tuc: cut text (or bytes) where a delimiter matches, then keep what is needed.

mod args;
mod bounds;
mod cut_bytes;
mod fast;
mod help;
mod reader;

include!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/cut_str.rs"));

use std::io::{BufWriter, Write};
use std::io::IsTerminal;

fn main() {
    let raw: Vec<String> = std::env::args().skip(1).collect();
    let opts = match args::parse(&raw) {
        Ok(args::ParseOutcome::Done) => return,
        Ok(args::ParseOutcome::Options(o)) => o,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };
    if raw.is_empty() {
        print!("{}", help::colored_long_version());
        return;
    }
    let code = match real_main(&opts) {
        Ok(()) => 0,
        Err(e) => {
            let _ = std::io::stdout().flush();
            eprintln!("{}", e);
            1
        }
    };
    std::process::exit(code);
}

fn real_main(opts: &args::Options) -> Result<(), String> {
    // validations shared by every mode
    if let Some(re) = &opts.regex {
        if let Err(e) = regex::Regex::new(re) {
            return Err(format!(
                "tuc: runtime error. The regular expression is malformed. {}",
                e
            ));
        }
    }
    if opts.json {
        if !opts.join {
            return Err("tuc: runtime error. Using both --json and --no-join is not permitted".to_string());
        }
        if opts.replace.is_some() {
            return Err("tuc: runtime error. The use of --replace with --json is not supported".to_string());
        }
        if opts.mode == args::Mode::Bytes || opts.mode == args::Mode::Lines {
            return Err("tuc: runtime error. --json support is available only for --fields and --characters".to_string());
        }
    }
    if opts.mode == args::Mode::Characters && !opts.join {
        return Err("tuc: runtime error. Since --characters implies --join, you can't pass --no-join".to_string());
    }
    if opts.replace.is_some() && !opts.join {
        return Err("tuc: runtime error. Can't use --no-join when using --replace, which implies --join".to_string());
    }
    if opts.regex.is_some() && opts.join && opts.replace.is_none() {
        return Err("tuc: runtime error. Cannot use --regex and --join without --replace-delimiter".to_string());
    }
    // parse the bounds now so that parse errors precede the runtime ones
    let bounds_str = opts.bounds.clone().unwrap_or_else(|| "1:".to_string());
    if let Err(e) = crate::bounds::userboundslist::UserBoundsList::parse(&bounds_str) {
        return Err(format!("failed to parse '{}': {}", bounds_str, e.message()));
    }
    if opts.fixed_memory.is_some() {
        crate::fast::check(opts)?;
    }
    let input = match &opts.file {
        Some(path) => {
            let md = std::fs::metadata(path);
            match md {
                Ok(m) => {
                    if m.is_dir() {
                        return Err(format!(
                            "tuc: runtime error. The path \"{}\" is not a file",
                            path
                        ));
                    }
                    match crate::reader::Input::from_file(path, opts.no_mmap) {
                        Ok(i) => i,
                        Err(e) => {
                            return Err(format!(
                                "Error: {}.\nWas attempting to read \"{}\"",
                                e, path
                            ))
                        }
                    }
                }
                Err(_) => {
                    return Err(format!(
                        "tuc: runtime error. The file \"{}\" does not exist",
                        path
                    ))
                }
            }
        }
        None => crate::reader::Input::from_stdin(opts.no_mmap),
    };
    let stdout = std::io::stdout();
    let mut w = BufWriter::new(stdout.lock());
    let res = if opts.fixed_memory.is_some() {
        crate::fast::run(input, opts, &mut w)
    } else if opts.mode == args::Mode::Bytes {
        crate::cut_bytes::run(input, opts, &mut w)
    } else {
        crate::cut_str::run(input, opts, &mut w)
    };
    let _ = w.flush();
    res
}

fn _unused_is_terminal() {
    let _ = std::io::stdout().is_terminal();
}
